import{_ as a,o as i,c as t,ao as s}from"./chunks/framework.CpiZ2d4R.js";const u=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md","lastUpdated":null}'),n={name:"guide/compatibility.md"};function o(r,e,l,p,c,d){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="Compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#Compatibility" aria-label="Permalink to &quot;Compatibility {#Compatibility}&quot;">​</a></h1><h2 id="Julia-and-package-versions" tabindex="-1">Julia and package versions <a class="header-anchor" href="#Julia-and-package-versions" aria-label="Permalink to &quot;Julia and package versions {#Julia-and-package-versions}&quot;">​</a></h2><p><code>VineCopulas.jl</code> supports Julia 1.10 and newer. Version 0.1.1 requires <code>Copulas.jl</code> 0.1.40 or newer within the 0.1 series.</p><p>The CI matrix tests the package on Julia 1.10 and the current Julia release.</p><h2 id="Copulas.jl-interoperability" tabindex="-1">Copulas.jl interoperability <a class="header-anchor" href="#Copulas.jl-interoperability" aria-label="Permalink to &quot;Copulas.jl interoperability {#Copulas.jl-interoperability}&quot;">​</a></h2><p>The public construction API keeps the mathematical parameter domains implemented by <code>Copulas.jl</code>. For example, direct construction such as</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ClaytonCopula</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, θ)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TCopula</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ν, Σ)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">GumbelCopula</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, θ)</span></span></code></pre></div><p>continues to use the corresponding <code>Copulas.jl</code> domain.</p><p>Automatic vine selection can use narrower <strong>candidate parameter domains</strong>. These bounds are internal to model selection and are chosen to align the candidate space with <code>vinecopulib</code> where external parity is required. They do not redefine the public copula families. See <a href="./../fitting/controls">Controls and parameter domains</a>.</p><h2 id="rvinecopulib" tabindex="-1">rvinecopulib <a class="header-anchor" href="#rvinecopulib" aria-label="Permalink to &quot;rvinecopulib {#rvinecopulib}&quot;">​</a></h2><p><code>rvinecopulib</code> is used as an external reference for the correctness gate. Raw R-vine matrices are not compared as strings because equivalent vines can have different matrix representations. Correctness checks compare represented edges, families, rotations, parameters, likelihoods, Rosenblatt transforms, and inverse transforms.</p><h2 id="Documentation-versions" tabindex="-1">Documentation versions <a class="header-anchor" href="#Documentation-versions" aria-label="Permalink to &quot;Documentation versions {#Documentation-versions}&quot;">​</a></h2><p>The documentation deployment keeps separate tagged and development sites. Use <code>stable</code> for the latest registered release and <code>dev</code> for the current <code>main</code> branch; retained patch releases are available from the version selector.</p>`,13)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
